import heapq

def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None
    queue = [(0, start)]
    path = {}
    path[start] = (None, 0)
    while queue:
        dist, node = heapq.heappop(queue)
        if node == goal:
            path_list = []
            while node is not None:
                path_list.append(node)
                node = path[node][0]
            return path_list[::-1]
        for neighbor in graph[node]:
            new_dist = dist + 1
            if neighbor not in path or new_dist < path[neighbor][1]:
                path[neighbor] = (node, new_dist)
                heapq.heappush(queue, (new_dist, neighbor))
    return None
